-- ============================================================================
-- SRM R&D PORTAL — SCHOLAR CURRENT STATUS TABLE & INITIAL IMPORT
-- Created: 2026-11-11
-- Source files:
--   1. Backend/research scholar status/ET scholar status.xlsx (291 records)
--   2. Backend/research scholar status/FLABS scholar status.xlsx (165 records)
--   3. Backend/research scholar status/Management scholar status.xlsx (37 records)
-- Total records: 493
-- ============================================================================

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

DROP TABLE IF EXISTS public.scholar_current_status CASCADE;

CREATE TABLE public.scholar_current_status (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    scholar_id UUID REFERENCES public.research_scholars(id) ON DELETE SET NULL,
    business_unit TEXT NOT NULL,
    registration_number TEXT,
    scholar_name TEXT NOT NULL,
    department TEXT,
    supervisor_name TEXT,
    enrollment_year INTEGER,
    category TEXT,
    current_status TEXT DEFAULT '',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_by TEXT
);

-- Performance Indexes
CREATE INDEX idx_scholar_current_status_reg_no ON public.scholar_current_status(registration_number);
CREATE INDEX idx_scholar_current_status_scholar_id ON public.scholar_current_status(scholar_id);
CREATE INDEX idx_scholar_current_status_supervisor ON public.scholar_current_status(supervisor_name);
CREATE INDEX idx_scholar_current_status_bu_dept ON public.scholar_current_status(business_unit, department);

-- Row Level Security & Public Access
ALTER TABLE public.scholar_current_status ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public full access on scholar_current_status" ON public.scholar_current_status;
CREATE POLICY "Public full access on scholar_current_status"
    ON public.scholar_current_status FOR ALL USING (true) WITH CHECK (true);

-- Auto-update updated_at timestamp trigger
CREATE OR REPLACE FUNCTION update_scholar_current_status_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_scholar_current_status_updated_at ON public.scholar_current_status;
CREATE TRIGGER trg_scholar_current_status_updated_at
    BEFORE UPDATE ON public.scholar_current_status
    FOR EACH ROW EXECUTE FUNCTION update_scholar_current_status_timestamp();

